import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"BI 报表可视化编辑器（amis-reports）","description":"","frontmatter":{},"headers":[],"relativePath":"products/amis-reports.md","filePath":"products/amis-reports.md"}'),o={name:"products/amis-reports.md"};function s(l,t,d,h,n,p){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="bi-报表可视化编辑器-amis-reports" tabindex="-1">BI 报表可视化编辑器（amis-reports） <a class="header-anchor" href="#bi-报表可视化编辑器-amis-reports" aria-label="Permalink to &quot;BI 报表可视化编辑器（amis-reports）&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>爱速搭报表是基于 ECharts 实现的图表功能组件，旨在为用户提供简单和快捷的可视化报表能力，帮助用户在爱速搭平台上快速设计常见的数据报表页和大屏报表效果页。</p><h3 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h3><ol><li>支持22种报表组件：包括数值指标、环形进度图、仪表盘、柱状图（水平、堆叠、双向对比）、饼图、玫瑰图、环形图、折线图、堆叠面积图、雷达图、漏斗图、词云、地图（世界、中国、省市级）、阶梯瀑布图、散点图、日历图、气泡图、气泡地图及桑基图；</li><li>支持对接5种数据源：静态JSON、内外API数据、上下文数据、实体数据源和数据集；</li><li>支持通过上下文数据和事件动作实现报表联动，以及自定义报表数据下钻功能；</li><li>支持对接主题（含主题数据色），以及支持运行时实时切换，可用于实现“一键换肤”功能；</li><li>支持行转列对比功能；</li><li>支持同类型报表组件快速切换；</li><li>支持大屏报表可视化设计；</li><li>支持标题、图例、标签、提示、X轴和Y轴等120+种报表属性配置。</li></ol><h2 id="使用入口" tabindex="-1">使用入口 <a class="header-anchor" href="#使用入口" aria-label="Permalink to &quot;使用入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>地址</th></tr></thead><tbody><tr><td>在线试用地址</td><td><a href="https://wibetter.github.io/amis-editor-demo/reports-demo/index.html#/edit/0" target="_blank" rel="noreferrer">https://wibetter.github.io/amis-editor-demo/reports-demo/index.html#/edit/0</a></td></tr><tr><td>NPM 地址</td><td><a href="https://www.npmjs.com/package/amis-reports" target="_blank" rel="noreferrer">https://www.npmjs.com/package/amis-reports</a></td></tr></tbody></table>',7)])])}const _=e(o,[["render",s]]);export{c as __pageData,_ as default};
